import{_ as s,l as n,o as a,c as o,v as r,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"增量解析 tree-sitter","description":"","frontmatter":{"title":"增量解析 tree-sitter","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/incremental-parsing.md","filePath":"cs/incremental-parsing.md","lastUpdated":1789023840000}'),h={name:"cs/incremental-parsing.md"};function E(m,e,_,u,A,f){const i=n("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="增量解析-tree-sitter" tabindex="-1">增量解析 tree-sitter <a class="header-anchor" href="#增量解析-tree-sitter" aria-label="Permalink to &quot;增量解析 tree-sitter&quot;">​</a></h1><div class="epigraph"><p>源文本改了一处，分析树只重算受影响的区间；编辑器要的是毫秒级更新，不是整文件再跑一遍 yyparse。</p><footer>—— 据 Wagner and Graham, Incremental Analysis of Real Programming Languages, 1998；tree-sitter 设计文档整理</footer></div><p>上一课<a href="/cs/parse-error-recovery">错误恢复</a>让整文件分析可以带着诊断走完。编辑会话里每次击键都全量 LALR 太贵。缺口是<strong>增量</strong>：把旧树与编辑区间对齐，复用未改子树。tree-sitter 用 GLR 方言与显式树，是这一课的工程锚点，不是唯一理论。本课不重写 GLR 分叉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全量分析 \\(O(n)\\) 对百万行尚可，对每次击键的交互不行。增量：保留具体语法树（带源区间），编辑映射到插入/删除区间，从该区间的祖先重新分析，其它子树当记号或子语言复用。缺口是<strong>复用条件</strong>，不是再定义 CFG。</p><p>错误节点：tree-sitter 在失败处插 <code>ERROR</code>，以便高亮与缩进仍工作。这与编译器的 <code>error</code> 产生式同类，目标是编辑器而非代码生成。</p><h3 id="复用不是「字节没改就语义没改」" tabindex="-1">复用不是「字节没改就语义没改」 <a class="header-anchor" href="#复用不是「字节没改就语义没改」" aria-label="Permalink to &quot;复用不是「字节没改就语义没改」&quot;">​</a></h3><p>宏、C 预处理器、依赖头文件会使「没改的区间」语义变。tree-sitter 默认按文件、按语言文法，不跑 cpp。真正编译器的增量要另做依赖图——本课只钉语法树增量。</p><p><span class="marginnote">Wagner–Graham 1998（PLDI）讨论真实语言的增量分析。tree-sitter 公开设计：GLR、显式冲突、增量。本课不把 Language Server 协议当文法理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保存旧树与旧文本。应用编辑，得新文本与脏区间。从脏区间对应的旧节点向上找到可再分析的边界（如函数、块）。在该子语言上跑分析器，把新子树接回。token 复用：词法也可增量，改空白尽量不动后继树。</p>',11)),(a(),l(c,null,{default:t(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%91%22%5D%20--%3E%20EDIT%5B%22%E7%BC%96%E8%BE%91%E5%8C%BA%E9%97%B4%22%5D%0A%20%20EDIT%20--%3E%20RE%5B%22%E5%B1%80%E9%83%A8%E5%86%8D%E5%88%86%E6%9E%90%22%5D%0A%20%20OLD%20--%3E%20REUSE%5B%22%E6%9C%AA%E8%84%8F%E5%AD%90%E6%A0%91%E5%A4%8D%E7%94%A8%22%5D%0A%20%20RE%20--%3E%20NEW%5B%22%E6%96%B0%E6%A0%91%22%5D%0A%20%20REUSE%20--%3E%20NEW%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与 Pratt/手写下降：增量更难，因为下降的调用栈没有显式区间树。这是「生成树、带位移」的动机。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最坏仍可能接近全量（在文件头改一个括号）。摊还在局部编辑上接近脏区大小。多语言嵌入（Markdown 里的代码块）靠外部扫描器切片段，各片段独立文法——点名，不写完。</p><p>编译器中端（SSA、数据流）增量是另一问题：语法树没变的函数仍可能因内联热度重优化。本课停在前端树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现 tree-sitter 的 C 运行时，不讲查询语言。后课默认：编辑器增量 ≠ 编译器全量语义。下一课从树到属性：属性文法，给节点挂值而不必立刻手写访问者。</p><p>不要把增量解析当成类型检查的增量；名字解析跨文件时脏区会跳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增量：脏区间再分析，未改子树复用。</li><li>tree-sitter：GLR 树 + 错误节点，服务编辑器。</li><li>预处理器与跨文件语义不在复用假设里。</li><li>出处：Wagner and Graham, 1998；tree-sitter 文档；对照 Tomita GLR。</li></ul>',9))])}const D=s(h,[["render",E]]);export{T as __pageData,D as default};
